const segs = (list, fill, file) => list.map(seg =>
  `<path d="${file[seg.p]}" fill="${fill}"${seg.e ? ' fill-rule="evenodd" clip-rule="evenodd"' : ''}${seg.s ? ` stroke="${fill}"` : ''}/>`).join('');

/** style: 'solid-white' | 'solid-black' | 'line-white' | 'line-black' → <svg> 문자열 */
export function iconSvg(iconId, style, size = 60) {
  const def = DEFS[iconId];
  if (!def) return '';
  const body = style === 'solid-white' ? `<path d="${swP.p21faa600}" fill="white" opacity="0.8"/>${segs(def.sw, 'black', swP)}`
    : style === 'solid-black' ? `<path d="${sbP.p21faa600}" fill="black" opacity="0.8"/>${segs(def.sb, 'white', sbP)}`
    : style === 'line-white' ? segs(def.lw, 'white', lwP)
    : segs(def.lb, 'black', lbP);
  return `<svg width="${size}" height="${size}" viewBox="0 0 60 60" fill="none" style="display:block;flex-shrink:0">${body}</svg>`;
}

